+          tw`rounded-lg px-3`, 
+          { backgroundColor }
+        ]}
+        inputStyle={{ color: textColor }}
+        rightIcon={
+          searchWord ? (
+            <TouchableOpacity key="clear-button" onPress={handleClear} style={tw`p-2`}>
+              <ThemedText key="clear-icon" style={tw`text-gray-500`}>X</ThemedText>
