+    setIsPending(true);
+    try {
+        const token = await SecureStore.getItemAsync('authToken');
+              if (!token) {
+                throw new Error('No authentication token found');
+              }
+              
+      const response = await axios.get(`${apiUrl}/searchBar?searchTerm=${query}`
+        
