+                  params: { 
+                    bookName: item.bookName, /book-
+                    bookAuthor: item.bookAuthor 
+                  } 
+                })}
+                style={tw`p-4 bg-white rounded-lg mb-3`}
+              >
+                <ThemedText style={[tw`font-bold text-lg`, {color:textColor}]}>{item.bookName}</ThemedText>
+                <ThemedText style={tw`text-gray-500`}>{item.bookAuthor}</ThemedText>
